	@ParameterizedTest
	@EnumSource(QueryEvaluationMode.class)
	public void logicalTruthTablesPreserveErrorsAndBooleanResults(QueryEvaluationMode mode) {
		String[] operands = { "true", "false", "<urn:error>" };
		for (boolean optimize : List.of(false, true)) {
			for (String operator : List.of("&&", "||")) {
				for (int left = 0; left < operands.length; left++) {
					for (int right = 0; right < operands.length; right++) {
						Boolean expected = logicalResult(operator, left, right);
						for (int variables = 0; variables < 4; variables++) {
							String expression = ((variables & 1) == 0 ? operands[left] : "?a") + " " + operator
									+ " " + ((variables & 2) == 0 ? operands[right] : "?b");
							String source = "VALUES (?a ?b) { (" + operands[left] + " " + operands[right] + ") }";
							assertThat(evaluate(mode, "SELECT ?x WHERE { " + source + " BIND(" + expression
									+ " AS ?x) }", optimize)).as("%s, optimize=%s", expression, optimize)
											.singleElement()
											.satisfies(row -> assertThat(row.getValue("x"))
													.isEqualTo(expected == null ? null
															: BooleanLiteral.valueOf(expected)));
						}
					}
				}
			}
			for (String operand : List.of("7", "0", "'nonempty'", "''")) {
				for (String expression : List.of("true && ?a", "?a && true", "false || ?a", "?a || false",
						"?a && ?a", "?a || ?a")) {
					assertThat(evaluate(mode, "SELECT ?x WHERE { VALUES ?a { " + operand + " } BIND("
							+ expression + " AS ?x) }", optimize)).singleElement()
									.satisfies(row -> assertThat(row.getValue("x"))
											.isEqualTo(BooleanLiteral
													.valueOf(!operand.equals("0") && !operand.equals("''"))));
				}
			}
		}
	}

	@ParameterizedTest
	@EnumSource(QueryEvaluationMode.class)
	public void iriRejectsNonStringLiteralsBeforeBaseResolution(QueryEvaluationMode mode) {
		for (boolean optimize : List.of(false, true)) {
			for (String operand : List.of("123", "true", "'relative'@en", "'relative'^^<urn:datatype>",
					"BNODE()", "TRIPLE(<urn:s>, <urn:p>, 1)")) {
				for (String expression : List.of("IRI(" + operand + ")", "URI(" + operand + ")")) {
					assertThat(evaluate(mode, "BASE <https://example.org/base/> SELECT ?x WHERE { BIND("
							+ expression + " AS ?x) }", optimize)).as(expression)
									.singleElement()
									.satisfies(row -> assertThat(row.hasBinding("x")).isFalse());
				}
			}
			String[][] validControls = {
					{ "'relative'", "https://example.org/base/relative" },
					{ "\"relative\"^^xsd:string", "https://example.org/base/relative" },
					{ "'https://example.org/base/absolute'", "https://example.org/base/absolute" },
					{ "\"https://example.org/base/typed\"^^xsd:string", "https://example.org/base/typed" },
					{ "<https://example.org/base/from-iri>", "https://example.org/base/from-iri" }
			};
			for (String function : List.of("IRI", "URI")) {
				for (String[] control : validControls) {
					String query = "BASE <https://example.org/base/> PREFIX xsd: "
							+ "<http://www.w3.org/2001/XMLSchema#> SELECT ?x WHERE { BIND(" + function + "("
							+ control[0] + ") AS ?x) }";
					assertThat(evaluate(mode, query, optimize))
							.as("%s(%s), optimize=%s", function, control[0], optimize)
							.singleElement()
							.satisfies(row -> {
								assertThat(row.getValue("x")).isInstanceOf(IRI.class);
								assertThat(row.getValue("x")).isEqualTo(
										SimpleValueFactory.getInstance().createIRI(control[1]));
							});
				}
			}
		}
	}

	@ParameterizedTest
	@EnumSource(QueryEvaluationMode.class)
	public void queryLevelRuntimeIfConditionErrorSkipsBothBranchesAfterPrecompile(QueryEvaluationMode mode) {
		AtomicInteger conditionCalls = new AtomicInteger();
		AtomicInteger innerThenCalls = new AtomicInteger();
		AtomicInteger innerElseCalls = new AtomicInteger();
		AtomicInteger outerThenCalls = new AtomicInteger();
		AtomicInteger outerElseCalls = new AtomicInteger();
		Function condition = countedFunction("urn:rdf4j:test:if-runtime-error", conditionCalls, null, true);
		Function innerThen = countedFunction("urn:rdf4j:test:if-inner-then", innerThenCalls,
				BooleanLiteral.TRUE, false);
		Function innerElse = countedFunction("urn:rdf4j:test:if-inner-else", innerElseCalls,
				BooleanLiteral.FALSE, false);
		Function outerThen = countedFunction("urn:rdf4j:test:if-outer-then", outerThenCalls,
				SimpleValueFactory.getInstance().createLiteral("then"), false);
		Function outerElse = countedFunction("urn:rdf4j:test:if-outer-else", outerElseCalls,
				SimpleValueFactory.getInstance().createLiteral("else"), false);
		FunctionRegistry registry = FunctionRegistry.getInstance();
		registry.add(condition);
		registry.add(innerThen);
		registry.add(innerElse);
		registry.add(outerThen);
		registry.add(outerElse);
		try {
			for (boolean optimize : List.of(false, true)) {
				conditionCalls.set(0);
				innerThenCalls.set(0);
				innerElseCalls.set(0);
				outerThenCalls.set(0);
				outerElseCalls.set(0);
				DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
				strategy.setQueryEvaluationMode(mode);
				ParsedQuery parsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL,
						"SELECT ?result WHERE { BIND(IF(isIRI(IF(<urn:rdf4j:test:if-runtime-error>(), "
								+ "<urn:rdf4j:test:if-inner-then>(), <urn:rdf4j:test:if-inner-else>())), "
								+ "<urn:rdf4j:test:if-outer-then>(), <urn:rdf4j:test:if-outer-else>()) AS ?result) }",
						null);
				TupleExpr expression = parsed.getTupleExpr();
				if (optimize) {
					expression = strategy.optimize(expression, new EvaluationStatistics(),
							EmptyBindingSet.getInstance());
				}
				var evaluationStep = strategy.precompile(expression);
				assertThat(conditionCalls).as("condition calls during precompile, optimize=%s", optimize).hasValue(0);
				assertThat(innerThenCalls).as("inner then calls during precompile, optimize=%s", optimize).hasValue(0);
				assertThat(innerElseCalls).as("inner else calls during precompile, optimize=%s", optimize).hasValue(0);
				assertThat(outerThenCalls).as("outer then calls during precompile, optimize=%s", optimize).hasValue(0);
				assertThat(outerElseCalls).as("outer else calls during precompile, optimize=%s", optimize).hasValue(0);
				try (CloseableIteration<BindingSet> rows = evaluationStep.evaluate(EmptyBindingSet.getInstance())) {
					assertThat(QueryResults.asList(rows)).singleElement()
							.satisfies(row -> assertThat(row.hasBinding("result")).isFalse());
				}
				assertThat(conditionCalls).as("runtime condition calls, optimize=%s", optimize).hasValue(1);
				assertThat(innerThenCalls).as("inner then branch calls, optimize=%s", optimize).hasValue(0);
				assertThat(innerElseCalls).as("inner else branch calls, optimize=%s", optimize).hasValue(0);
				assertThat(outerThenCalls).as("outer then branch calls, optimize=%s", optimize).hasValue(0);
				assertThat(outerElseCalls).as("outer else branch calls, optimize=%s", optimize).hasValue(0);
			}
		} finally {
			registry.remove(condition);
			registry.remove(innerThen);
			registry.remove(innerElse);
			registry.remove(outerThen);
			registry.remove(outerElse);
		}
	}

	private static Function countedFunction(String uri, AtomicInteger calls, Value result, boolean fail) {
		return new Function() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public boolean mustReturnDifferentResult() {
				return true;
			}

			@Override
			public Value evaluate(ValueFactory factory, Value... args) {
				calls.incrementAndGet();
				if (fail) {
					throw new ValueExprEvaluationException("runtime IF condition error");
				}
				return result;
			}
		};
	}

	@Test
	public void erroneousIfConditionEvaluatesNeitherBranch() {
		AtomicInteger selected = new AtomicInteger();
		QueryValueEvaluationStep branch = bindings -> {
			selected.incrementAndGet();
			return BooleanLiteral.TRUE;
		};
		QueryValueEvaluationStep condition = new QueryValueEvaluationStep.Fail("condition error");
		IfValueEvaluationStep step = new IfValueEvaluationStep(branch, condition, branch);
		assertThrows(ValueExprEvaluationException.class, () -> step.evaluate(EmptyBindingSet.getInstance()));
		assertThat(selected).hasValue(0);
	}

	@Test
	public void logicalStepsShortCircuitAndPreserveIncompatibleErrors() {
		AtomicInteger evaluations = new AtomicInteger();
		QueryValueEvaluationStep error = bindings -> {
			evaluations.incrementAndGet();
			throw new ValueExprEvaluationException("unselected operand");
		};
		QueryValueEvaluationStep truth = bindings -> BooleanLiteral.TRUE;
		QueryValueEvaluationStep falsity = bindings -> BooleanLiteral.FALSE;
		assertThat(new AndValueEvaluationStep(falsity, error).evaluate(EmptyBindingSet.getInstance()))
				.isEqualTo(BooleanLiteral.FALSE);
		assertThat(new OrValueEvaluationStep(truth, error).evaluate(EmptyBindingSet.getInstance()))
				.isEqualTo(BooleanLiteral.TRUE);
		assertThat(evaluations).hasValue(0);
		QueryValueEvaluationStep incompatible = bindings -> SimpleValueFactory.getInstance().createIRI("urn:error");
		assertThrows(ValueExprEvaluationException.class,
				() -> new AndValueEvaluationStep(incompatible, truth).evaluate(EmptyBindingSet.getInstance()));
		assertThrows(ValueExprEvaluationException.class, () -> QueryValueEvaluationStepSupplier
				.prepareAnd(incompatible, truth)
				.evaluate(EmptyBindingSet.getInstance()));
	}

	private static Boolean logicalResult(String operator, int left, int right) {
		if (operator.equals("&&")) {
			return left == 1 || right == 1 ? Boolean.FALSE : left == 2 || right == 2 ? null : Boolean.TRUE;
		}
		return left == 0 || right == 0 ? Boolean.TRUE : left == 2 || right == 2 ? null : Boolean.FALSE;
	}

